parameters.text:
=Voici les articles récupérés aujourd'hui. Analyse-les, sélectionne les 3 meilleurs selon mes intérêts, rédige la newsletter dense et génère le code HTML complet comme demandé dans tes instructions système.

DONNÉES BRUTES DES ARTICLES À TRAITER :
{{ 
$input.all()[0].json.data.map((item, index) => {
  return `Article [${index + 1}] :
  - Titre : ${item.title}
  - Description : ${item.description || 'Pas de description'}
  - LIEN_DIRECT_ET_COMPLET_DE_L_ARTICLE : ${item.url}
  - Image d'illustration : ${item.image || ''}
  - Date de diffusion : ${item.publishedAt || ''}
  - Source : ${item.source || 'Média'}`;
}).join('\n\n') 
}}

parameters.jsCode:
const inputData = $input.all();

if (inputData.length > 0 && inputData[0].json.articles) {
  return inputData[0].json.articles.map(article => {
    return {
      json: {
        title: article.title,
        description: article.description,
        url: article.url,
        image: article.image,
        publishedAt: article.publishedAt,
        source: article.source?.name || 'GNews'
      }
    };
  });
}

return [];

